    47|  const trimmed = url.trim();
    48|  // git@github.com:owner/repo.git
    49|  const sshMatch = trimmed.match(/git@github\.com:([^/]+)\/([^/\s]+?)(?:\.git)?$/);
    50|  if (sshMatch) return { owner: sshMatch[1], repo: sshMatch[2] };
    51|  // https://github.com/owner/repo(.git)?
